@RunWith(AndroidJUnit4.class)
public class AttachmentLayoutRegressionTest {
 private Object field(Activity a,String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(a);}
 private void call(Activity a,String name,Class<?>[] types,Object... args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(a,args);}
 private View described(View v,String desc){if(desc.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View hit=described(g.getChildAt(i),desc);if(hit!=null)return hit;}}return null;}
 private int[] positions(View row){int[] result=new int[3];for(int i=0;i<3;i++){int[] p=new int[2];row.findViewWithTag("message-action-"+i).getLocationOnScreen(p);result[i]=p[0];}return result;}
 @Test public void twoCardsPlusAndStableRevisionCoordinatesBothRoles()throws Exception{
  Instrumentation ins=InstrumentationRegistry.getInstrumentation();Context c=ins.getTargetContext();SharedPreferences prefs=c.getSharedPreferences("chat",0);Map<String,?> backup=new HashMap<>(prefs.getAll());Activity activity=null;
  try{
   JSONObject session=new JSONObject().put("id","attachment-layout").put("title","fixture").put("titleManual",true).put("messages",new JSONArray().put(new JSONObject().put("id","u").put("user",true).put("text","question")).put(new JSONObject().put("id","a").put("user",false).put("text","answer")));
   prefs.edit().clear().putString("sessions",new JSONArray().put(session).toString()).putString("currentSessionId","attachment-layout").putString("themeMode","dark").commit();activity=ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity a=activity;ins.waitForIdleSync();
   ins.runOnMainSync(()->{ImageButton plus=(ImageButton)described(a.getWindow().getDecorView(),"添加附件");assertNotNull(plus);float density=c.getResources().getDisplayMetrics().density;assertEquals(20,Math.round(plus.getDrawable().getIntrinsicWidth()/density));assertTrue("Attachment button needs at least a 48dp touch target",Math.round(plus.getWidth()/density)>=48);android.graphics.Bitmap actual=android.graphics.Bitmap.createBitmap(plus.getDrawable().getIntrinsicWidth(),plus.getDrawable().getIntrinsicHeight(),android.graphics.Bitmap.Config.ARGB_8888);android.graphics.drawable.Drawable expected=c.getDrawable(R.drawable.ic_attach);expected.setTintList(plus.getImageTintList());android.graphics.Bitmap reference=android.graphics.Bitmap.createBitmap(actual.getWidth(),actual.getHeight(),actual.getConfig());plus.getDrawable().setBounds(0,0,actual.getWidth(),actual.getHeight());plus.getDrawable().draw(new android.graphics.Canvas(actual));expected.setBounds(0,0,actual.getWidth(),actual.getHeight());expected.draw(new android.graphics.Canvas(reference));assertTrue(actual.sameAs(reference));plus.performClick();});android.os.SystemClock.sleep(250);ins.waitForIdleSync();
   ins.runOnMainSync(()->{try{LinearLayout choices=(LinearLayout)field(a,"attachmentChoices");assertTrue(choices.isShown());assertEquals(2,choices.getChildCount());assertEquals("图片",((TextView)choices.getChildAt(0)).getText().toString());assertEquals("文件",((TextView)choices.getChildAt(1)).getText().toString());call(a,"setAttachmentChoices",new Class[]{boolean.class},false);}catch(Exception e){throw new AssertionError(e);}});android.os.SystemClock.sleep(250);
   for(boolean user:new boolean[]{true,false}){
    ins.runOnMainSync(()->{try{call(a,"restoreSession",new Class[]{JSONObject.class},session);}catch(Exception e){throw new AssertionError(e);}});android.os.SystemClock.sleep(150);ins.waitForIdleSync();int[][] before=new int[1][];int[] width=new int[1];
    ins.runOnMainSync(()->{try{View row=((LinearLayout)field(a,"messageList")).getChildAt(user?1:2);before[0]=positions(row);width[0]=((ViewGroup)row).getChildAt(0).getWidth();JSONObject revised=new JSONObject(session.toString());ConversationBranches.edit(new JSONArray().put(revised),"attachment-layout",user?"u":"a","variant",false);call(a,"restoreSession",new Class[]{JSONObject.class},revised);}catch(Exception e){throw new AssertionError(e);}});android.os.SystemClock.sleep(150);ins.waitForIdleSync();
    ins.runOnMainSync(()->{try{View row=((LinearLayout)field(a,"messageList")).getChildAt(user?1:2);assertArrayEquals(before[0],positions(row));assertEquals(width[0],((ViewGroup)row).getChildAt(0).getWidth());View nav=row.findViewWithTag("message-versions");assertNotNull(nav);int[] p=new int[2];nav.getLocationOnScreen(p);assertTrue("revision right="+(p[0]+nav.getWidth())+" edit left="+before[0][0],p[0]+nav.getWidth()<=before[0][0]);assertEquals(3,((ViewGroup)row.findViewWithTag("message-actions")).getChildCount());}catch(Exception e){throw new AssertionError(e);}});
   }
   Intent picked=new Intent();ClipData fixtures=ClipData.newRawUri("fixtures",Uri.parse("content://com.changyu.ochat.test.attachments/one"));fixtures.addItem(new ClipData.Item(Uri.parse("content://com.changyu.ochat.test.attachments/two")));picked.setClipData(fixtures);
   ins.runOnMainSync(()->{try{call(a,"onActivityResult",new Class[]{int.class,int.class,Intent.class},41,Activity.RESULT_OK,picked);}catch(Exception e){throw new AssertionError(e);}});
   for(int wait=0;wait<100;wait++){boolean[] loading={true};ins.runOnMainSync(()->{try{loading[0]=(Boolean)field(a,"attachmentLoading");}catch(Exception e){throw new AssertionError(e);}});if(!loading[0])break;android.os.SystemClock.sleep(50);}
   ins.runOnMainSync(()->{try{assertFalse((Boolean)field(a,"attachmentLoading"));assertEquals(2,((List<?>)field(a,"pendingAttachments")).size());call(a,"onActivityResult",new Class[]{int.class,int.class,Intent.class},41,Activity.RESULT_CANCELED,null);assertEquals(2,((List<?>)field(a,"pendingAttachments")).size());((EditText)field(a,"composer")).setText("local fixtures");call(a,"sendMessage",new Class[]{});}catch(Exception e){throw new AssertionError(e);}});ins.waitForIdleSync();
   JSONObject storedSession=MessageEdits.findSession(new JSONArray(prefs.getString("sessions","[]")),"attachment-layout");JSONArray savedMessages=storedSession.getJSONArray("messages");JSONObject sent=savedMessages.getJSONObject(savedMessages.length()-2);assertEquals(2,sent.getJSONArray("attachments").length());assertFalse(sent.optString("text").contains("Fixture contents"));assertEquals("Fixture contents one",sent.getJSONArray("attachments").getJSONObject(0).optString("payloadSnapshot"));assertEquals("Fixture contents two",sent.getJSONArray("attachments").getJSONObject(1).optString("payloadSnapshot"));
   JSONArray requestHistory=new JSONArray();for(int i=0;i<savedMessages.length();i++){JSONObject m=savedMessages.getJSONObject(i);if(!m.optBoolean("error"))requestHistory.put(new JSONObject().put("role",m.optBoolean("user")?"user":"assistant").put("content",m.optString("text")));}call(a,"restoreHistoryAttachments",new Class[]{JSONObject.class,JSONArray.class},storedSession,requestHistory);JSONArray sentContent=requestHistory.getJSONObject(requestHistory.length()-1).getJSONArray("content");assertEquals(3,sentContent.length());assertTrue(sentContent.toString().contains("Fixture contents one"));assertTrue(sentContent.toString().contains("Fixture contents two"));
   String sentId=sent.getString("id");ins.runOnMainSync(()->{try{call(a,"applyMessageEdit",new Class[]{String.class,String.class,String.class,boolean.class},"attachment-layout",sentId,null,true);}catch(Exception e){throw new AssertionError(e);}});ins.waitForIdleSync();assertEquals(2,MessageEdits.findSession(new JSONArray(prefs.getString("sessions","[]")),"attachment-layout").getJSONArray("messages").getJSONObject(savedMessages.length()-2).getJSONArray("attachments").length());
  }finally{if(activity!=null){Activity a=activity;ins.runOnMainSync(a::finish);ins.waitForIdleSync();}SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> entry:backup.entrySet()){String k=entry.getKey();Object v=entry.getValue();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,(Set<String>)v);}e.commit();}
 }
 @Test public void clipDataAllDescriptorsRequestProtocolsAndRetryPersistence()throws Exception{
  Intent data=new Intent().setData(Uri.parse("content://fixture/one"));ClipData clip=ClipData.newRawUri("fixture",data.getData());clip.addItem(new ClipData.Item(Uri.parse("content://fixture/two")));clip.addItem(new ClipData.Item(Uri.parse("content://fixture/three")));data.setClipData(clip);assertEquals(3,AttachmentBatch.collect(data).size());assertTrue(AttachmentBatch.collect(null).isEmpty());
  List<JSONObject> descriptors=new ArrayList<>();for(Uri uri:AttachmentBatch.collect(data))descriptors.add(new JSONObject().put("uri",uri.toString()).put("mime","text/plain").put("displayName",uri.getLastPathSegment()));
  JSONArray content=AttachmentBatch.content("question",descriptors,Arrays.asList("first fixture","data:image/jpeg;base64,fixture","third fixture"));assertEquals(4,content.length());JSONArray history=new JSONArray().put(new JSONObject().put("role","user").put("content",content));ChatApiClient client=new ChatApiClient();assertEquals(4,client.requestBody("fixture",history,.7,128,1,"default",ChatApiClient.CHAT_COMPLETIONS,SearchOptions.OFF).getJSONArray("messages").getJSONObject(0).getJSONArray("content").length());JSONArray responses=client.requestBody("fixture",history,.7,128,1,"default",ChatApiClient.RESPONSES,SearchOptions.OFF).getJSONArray("input").getJSONObject(0).getJSONArray("content");assertEquals(4,responses.length());assertEquals("input_image",responses.getJSONObject(2).getString("type"));
  JSONArray attachments=new JSONArray();for(JSONObject d:descriptors)attachments.put(d);JSONObject s=new JSONObject().put("id","fixture").put("messages",new JSONArray().put(new JSONObject().put("id","u").put("user",true).put("text","question").put("attachments",attachments)));JSONArray sessions=new JSONArray().put(s);ConversationBranches.edit(sessions,"fixture","u",null,true);String stored=sessions.toString();assertFalse(stored.contains("base64"));assertEquals(3,new JSONArray(stored).getJSONObject(0).getJSONArray("messages").getJSONObject(0).getJSONArray("attachments").length());
 }
}
